/*
  src/services/api.js
  --------------------
  Handles ALL communication between React and FastAPI.

  WHY a separate file?
    Components stay clean. URLs live in one place only.

  WHAT IS AXIOS?
    JavaScript HTTP library — like Python's "requests" but for JS.

    Without axios:       With axios (cleaner):
    fetch('/api/...')    const {data} = await axios.get('/api/...')
     .then(r => r.json())
     .then(d => use(d))

    Axios auto-parses JSON, handles errors better, supports timeouts.
*/

import axios from 'axios';

// Backend URL — reads from .env file, falls back to localhost
const BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

// Pre-configured axios instance — all requests use this
const api = axios.create({
  baseURL: BASE_URL,
  headers: {
    'Content-Type': 'application/json'
  },
  timeout: 60000 // 60s — summaries can be slow
});

/*
  searchPapers()
  ──────────────
  Fetches papers from FastAPI.

  What is async/await?
    JS is async — it doesn't block while waiting for network.
    async  → marks function as asynchronous
    await  → "pause here until this Promise resolves"

    Like Python's async/await — same concept!

  What is a Promise?
    A placeholder for a future value.
    const data = await searchPapers(...)
    ← pauses until FastAPI responds, then continues
*/
export const searchPapers = async (query, limit = 10, source = 'arxiv', summarize = true) => {
  // axios.get builds URL: /api/papers/search?query=...&limit=...
  // params object → auto-converted to ?key=value pairs
  const response = await api.get('/api/papers/search', {
    params: {
      query,
      limit,
      source,
      summarize
    }
  });

  // response.data = JSON parsed automatically by axios
  // Shape: { query, total, papers: [...], source_used, summaries_enabled }
  return response.data;
};

// POST a single abstract for on-demand summarization
export const summarizePaper = async abstract => {
  const response = await api.post('/api/papers/summarize', {
    abstract
  });
  return response.data;
};

// Health check — called on app load
export const checkHealth = async () => {
  const response = await api.get('/api/papers/health');
  return response.data;
};
export default api;

